#include "KS/SRC/ks/FEMenu_shared.h"
class color; class PanelAnim;
class __attribute__((aligned(16))) PanelQuad {
    char data[0x194];
public:
    PanelQuad(const PanelQuad &);
    virtual ~PanelQuad();
    virtual void Init(float,float,float,float,float,float,float,float,float,float,float,float,float,char *);
    virtual void TurnOn(bool);
    virtual void SetLayer(int);
    virtual void Rotate(float);
    virtual void Rotate(float,float,float);
    virtual void Update(float);
    virtual void Draw(int=0,float=-1.0f);
    virtual void SetColor(float,float,float,float);
    virtual void SetColor(color);
    virtual void SetZ(float);
    virtual void SetUV(float,float,float,float);
    virtual bool IsOn() const;
    virtual void SetPos(float,float,float,float);
    virtual void SetPos(float,float);
    virtual void SetPos(float,float,float,float,float,float,float,float);
    virtual void GetPos(float &,float &,float &,float &);
    virtual void SetCenterX(float);
    virtual void SetCenterY(float);
    virtual void SetCenterPos(float,float);
    virtual void GetCenterPos(float &,float &);
};
void *operator new(unsigned int,unsigned int,const char *,int);
class ExtrasFrontEnd : public FEMultiMenu {
public:
    enum { ExtrasBeachesEntry, ExtrasSurfersEntry, ExtrasTrailersEntry,
        ExtrasHighScoreEntry, ExtrasScrapbookEntry, ExtrasCheatsEntry,
        ExtrasCreditsEntry, ExtrasWebsitesEntry, ExtrasLogbookEntry,
        ExtrasTHDemoEntry, ExtrasDemoEntryYes, ExtrasDemoEntryNo,
        ExtrasEndEntry };
private:
    int cur_index; void *sys; FEMenuEntry *entry[ExtrasEndEntry];
    FEMenu *surfers; FEMenu *beaches; FEMenu *trailers;
    void *extras; void *prompt; void *websites; void *cheat_menu;
    PanelQuad *videos[ExtrasEndEntry]; PanelQuad *website_box[9];
    PanelQuad *arrows[2][2]; bool saveCareerPrompt;
    int arrow_counter; int arrow_num;
public:
    void SetPQIndices();
};
#define NEW new(0, "KS/SRC/ks/ExtrasFrontEnd.cpp", 0)
void ExtrasFrontEnd::SetPQIndices()
{
	arrows[0][0] = GetPointer("ex_button_off_01");
	arrows[0][1] = GetPointer("ex_button_on_01");
	arrows[1][0] = GetPointer("ex_button_off_02");
	arrows[1][1] = GetPointer("ex_button_on_02");

	for(int i=0; i<ExtrasEndEntry; i++)
		videos[i] = NULL;

	videos[ExtrasBeachesEntry] = GetPointer("extras_case_beaches");
	videos[ExtrasSurfersEntry] = GetPointer("extras_case_surfers");
	videos[ExtrasTrailersEntry] = GetPointer("extras_case_trailer");
	videos[ExtrasCreditsEntry] = GetPointer("extras_case_credits");

	PanelQuad* tmp_box;
	for(int i=0; i<9; i++)
	{
		tmp_box = GetPointer(("ex_box_0"+stringx(i+1)).data());
		website_box[i] = NEW PanelQuad(*tmp_box);
	}

	float x_left, x_right, x_tmp, y1, y2;
	website_box[0]->GetPos(x_left, y1, x_tmp, y2);
	website_box[2]->GetPos(x_tmp, y1, x_right, y2);
	float flipped_right_edge = 640 - x_right;
	float website_box_offset = flipped_right_edge - x_left;

	for(int i=0; i<9; i++)
	{
		website_box[i]->GetCenterPos(x_tmp, y1);
		website_box[i]->SetCenterPos(x_tmp + website_box_offset, y1);
	}
}
